import React from 'react';

const StepList = ({ steps }) => {
  return (
    <div className="step-list">
      <h2>Steps</h2>
      <ul>
        {steps.map((step, index) => (
          <li key={index}>
            Type: {step.stepType}, Vehicle: {step.vehicle}, Station: {step.station}
            {/* Afficher d'autres détails des steps selon vos besoins */}
          </li>
        ))}
      </ul>
    </div>
  );
};

export default StepList;
